(()=>{'use strict';
const {Game,PLANTS,ENEMIES,LEVELS}=LawnGame,{Renderer,G}=LawnRenderer,$=id=>document.getElementById(id);
let intro=null,renderer=null,game=null,paused=true,finished=false,selected=null,hover=null,speed=1,grid=false,auto=false,last=0,cardEls={},toastTimer,helpWasPlaying=false,sound=false,soundLast={},tickCount=0;
let progress={unlocked:0,wins:[],best:0},storageOK=true;try{const data=JSON.parse(localStorage.getItem('pvz-day-v2'));if(data&&Number.isInteger(data.unlocked))progress={unlocked:Math.min(9,Math.max(0,data.unlocked)),wins:Array.isArray(data.wins)?data.wins.filter(n=>Number.isInteger(n)&&n>=0&&n<10):[],best:Math.max(0,Number(data.best)||0)};}catch{storageOK=false;}
function save(){try{localStorage.setItem('pvz-day-v2',JSON.stringify(progress));}catch{storageOK=false;}}
function toast(s){$('toast').textContent=s;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2200);}
const audioFiles={plant:'plantation',sun:'points',shoot:'pea_shoot',hit:'pea_hit',chomp:'chomp',kill:'zombie_fall',boom:'zombieFinalKill'};
function sfx(type){if(!sound||!audioFiles[type])return;const now=performance.now();if(now-(soundLast[type]||0)<(type==='chomp'?450:110))return;soundLast[type]=now;try{const a=new Audio(window.__ASSET_URLS__?.['audio/'+audioFiles[type]+'.mp3']||'assets/audio/'+audioFiles[type]+'.mp3');a.volume=type==='shoot'?.12:.3;const p=a.play();p?.catch(()=>{});}catch{}}
function overlay(tag,title,txt,buttons){$('overlay').hidden=false;$('overlayTag').textContent=tag;$('overlayTitle').textContent=title;$('overlayText').textContent=txt;$('overlayButtons').replaceChildren();for(const [label,fn,primary] of buttons){const b=document.createElement('button');b.textContent=label;if(primary)b.className='primary';b.onclick=fn;$('overlayButtons').append(b);}}
function home(){intro=null;game=null;paused=true;$('skipIntroBtn').hidden=true;$('levelSelect').hidden=true;$('play').hidden=true;$('home').hidden=false;$('levels').replaceChildren();LEVELS.forEach((l,i)=>{const b=document.createElement('button');b.className='level-card'+(progress.wins.includes(i)?' won':'');b.disabled=i>progress.unlocked;b.innerHTML=`<span class="status">${progress.wins.includes(i)?'完成 ✓':i>progress.unlocked?'未解锁':'可挑战'}</span><small>冒险 ${i+1} / 10</small><h3>${l.title.split(' · ')[1]}</h3><small>${(l.rows||[0,1,2,3,4]).length} 行草坪 · ${l.waves} 波</small>`;b.onclick=()=>start(i);if(i<=progress.unlocked){const preview=document.createElement('canvas');preview.className='level-preview';preview.width=120;preview.height=88;const ctx=preview.getContext('2d');ctx.fillStyle='#514837';ctx.fillRect(0,0,120,88);renderer.sprite(ctx,PLANTS[Object.keys(PLANTS)[i%9]].asset,24,6,72,72,0);b.append(preview);}$('levels').append(b);});$('continueBtn').setAttribute('aria-label',progress.wins.length?'继续冒险':'开始冒险');$('saveInfo').textContent=storageOK?`已完成 ${progress.wins.length}/10 关 · 无尽最高 ${progress.best} 波`:'当前浏览器暂不能保存进度，本次游戏仍可正常游玩。';}
function resume(){if(!game||finished)return;$('overlay').hidden=true;$('pauseBtn').textContent='暂停';last=performance.now();if(intro){intro.running=true;paused=true;$('skipIntroBtn').hidden=false;return;}paused=false;}
function finishIntro(){if(!intro)return;intro=null;$('skipIntroBtn').hidden=true;document.querySelector('.battlefield').classList.remove('introducing');$('pauseBtn').disabled=$('speedBtn').disabled=false;resume();hint();}
$('skipIntroBtn').onclick=finishIntro;

function hint(){if(!game)return;let text=selected==='shovel'?'铲子：点选要移除的植物，不退还阳光。':selected?`${PLANTS[selected].name} · ${PLANTS[selected].role}`:game.wave===0?(game.level===0?'先收集阳光，达到 100 后种下豌豆射手。':'先发展向日葵，再补齐每条路线的火力。'):'选择种子卡种植，点击阳光收集。';$('hint').textContent=text;}
function start(level=0,endless=false){if(!renderer)return;game=new Game(level,{endless});paused=true;intro={time:0,running:false};finished=false;selected=null;hover=null;speed=1;$('levelSelect').hidden=true;document.querySelector('.battlefield').classList.add('introducing');$('pauseBtn').disabled=$('speedBtn').disabled=true;$('speedBtn').textContent='1×';$('pauseBtn').textContent='暂停';$('home').hidden=true;$('play').hidden=false;$('levelTitle').textContent=game.cfg.title;makeCards();hint();draw();overlay('保卫你的草坪',game.cfg.title,game.endless?'所有植物已开放。僵尸不断来袭，每行只有一次割草机救场。':game.cfg.desc,[['开始种植',resume,true],['返回菜单',home]]);}
function makeCards(){$('cards').replaceChildren();cardEls={};game.available().forEach((type,i)=>{const d=PLANTS[type],b=document.createElement('button');b.className='card';b.title=`${d.name}：${d.role}`;b.setAttribute('aria-label',`${d.name}，${d.cost} 阳光，${d.role}`);b.innerHTML=`<img src="${renderer.images['card-'+d.asset+'.png'].src}" alt="${d.name}"><span class="cost">${d.cost}</span><span class="key">${i+1}</span><i class="cooldown" hidden></i><span class="cd-text" hidden></span>`;b.onclick=()=>{if(paused||finished)return;selected=selected===type?null:type;hint();updateHUD();};$('cards').append(b);cardEls[type]=b;});}
function updateHUD(){if(!game)return;$('sunValue').textContent=game.sun;$('waveLabel').textContent=game.wave===0?`僵尸将在 ${Math.max(0,Math.ceil(game.nextWave-game.time))} 秒后来袭`:`第 ${game.wave}${game.endless?'':` / ${game.cfg.waves}`} 波 · ${game.enemies.length} 只`;$('waveFill').style.width=(game.endless?Math.min(100,game.wave*4):game.wave/game.cfg.waves*100)+'%';for(const[type,b]of Object.entries(cardEls)){b.classList.toggle('selected',selected===type);b.setAttribute('aria-pressed',selected===type?'true':'false');b.classList.toggle('unaffordable',game.sun<PLANTS[type].cost);const cd=game.cooldowns[type]||0,cover=b.querySelector('.cooldown'),label=b.querySelector('.cd-text');cover.hidden=label.hidden=cd<=0;cover.style.height=(cd/PLANTS[type].cool*100)+'%';label.textContent=Math.ceil(cd);} $('shovelBtn').classList.toggle('active',selected==='shovel');}
function finish(){finished=true;paused=true;const won=game.state==='won';if(won){if(!progress.wins.includes(game.level))progress.wins.push(game.level);progress.unlocked=Math.max(progress.unlocked,Math.min(9,game.level+1));}if(game.endless)progress.best=Math.max(progress.best,Math.max(0,game.wave-1));save();const level=game.level,endless=game.endless;let buttons=[];if(won&&level<9)buttons.push(['下一关',()=>start(level+1),true]);if(won&&level===9)buttons.push(['挑战无尽',()=>start(0,true),true]);buttons.push(['重新挑战',()=>start(level,endless),!won],['返回菜单',home]);let text=`消灭 ${game.kills} 只僵尸 · 获得 ${game.score} 积分。`;if(won&&level<9){const unlock=LEVELS[level+1].unlock.map(k=>PLANTS[k].name).join('、');if(unlock)text+=`下一关可使用：${unlock}。`;}overlay(won?'关卡完成':'僵尸进入了你的家',won?'草坪守住了！':'僵尸吃掉了你的脑子！',text,buttons);}
function draw(){if(!renderer||!game)return;if(intro)LawnUI.drawIntro(renderer,$('board').getContext('2d'),game,intro.time);else renderer.draw($('board').getContext('2d'),game,selected,hover,{grid});updateHUD();}
function frame(now){const dt=Math.min(.08,(now-last)/1000||0);last=now;if(renderer&&game){if(intro){if(intro.running){intro.time+=dt;if(intro.time>=LawnUI.DURATION)finishIntro();}}else if(!paused){for(let i=0;i<speed;i++)game.tick(dt);if(auto)for(const s of [...game.suns])game.collect(s.id);let played=new Set();for(const e of game.events.splice(0)){if(!played.has(e.type)){sfx(e.type);played.add(e.type);}}if(game.state!=='playing'&&!finished)finish();}draw();}requestAnimationFrame(frame);}
function position(e){const r=$('board').getBoundingClientRect();const x=(e.clientX-r.left)*G.width/r.width,y=(e.clientY-r.top)*G.height/r.height;return{x,y,col:Math.floor((x-G.x)/G.w),row:Math.floor((y-G.y)/G.h)};}
$('board').addEventListener('pointermove',e=>{const p=position(e);hover=p.row>=0&&p.row<5&&p.col>=0&&p.col<9?p:null;});$('board').addEventListener('pointerleave',()=>hover=null);$('board').addEventListener('pointerdown',e=>{e.preventDefault();if(!game||paused||finished)return;const p=position(e);const sun=[...game.suns].reverse().find(s=>{const pos=renderer.sunPosition(s,game.time);return Math.hypot(p.x-pos.x,p.y-pos.y)<34;});if(sun){game.collect(sun.id);return;}if(p.row<0||p.row>=5||p.col<0||p.col>=9)return;if(selected==='shovel'){if(game.shovel(p.row,p.col)){selected=null;hint();}else toast('这里没有植物');}else if(selected){const result=game.place(selected,p.row,p.col);if(result.ok){selected=null;hint();}else toast(result.reason);}else toast('先选择上方的植物卡片');});
function pause(){if(!game||finished)return;if(intro){intro.running=false;}if(paused)resume();else{paused=true;$('pauseBtn').textContent='继续';overlay('暂停','休息一下','战斗已暂停。',[['继续游戏',resume,true],['重新开始',()=>start(game.level,game.endless)],['返回菜单',home]]);}}
$('pauseBtn').onclick=pause;$('menuBtn').onclick=()=>{if(!game)return;if(intro)intro.running=false;paused=true;overlay('返回菜单','离开这一关？','本关战斗会结束，已解锁的关卡会保留。',[['继续游戏',resume,true],['返回菜单',home]]);};$('homeLink').onclick=e=>{e.preventDefault();if(game)$('menuBtn').click();else home();};$('continueBtn').onclick=()=>start(progress.unlocked);$('endlessBtn').onclick=()=>start(0,true);$('speedBtn').onclick=()=>{speed=speed===1?2:1;$('speedBtn').textContent=speed+'×';};$('gridBtn').onclick=()=>{grid=!grid;$('gridBtn').classList.toggle('active',grid);};$('shovelBtn').onclick=()=>{if(paused||finished)return;selected=selected==='shovel'?null:'shovel';hint();};$('autoBtn').onclick=()=>{auto=!auto;$('autoBtn').textContent=`自动收光：${auto?'开':'关'}`;$('autoBtn').classList.toggle('active',auto);};$('soundBtn').onclick=()=>{sound=!sound;$('soundBtn').textContent=`声音：${sound?'开':'关'}`;if(sound)sfx('sun');};
function showHelp(){helpWasPlaying=!!game&&!paused;if(helpWasPlaying)paused=true;if(intro){intro.wasRunning=intro.running;intro.running=false;}$('help').showModal();}$('helpBtn').onclick=showHelp;$('almanacBtn').onclick=showHelp;$('menuHelpBtn').onclick=showHelp;$('closeHelp').onclick=()=>$('help').close();$('help').addEventListener('close',()=>{if(helpWasPlaying){paused=false;last=performance.now();}if(intro&&intro.wasRunning){intro.running=true;intro.wasRunning=false;}helpWasPlaying=false;});
function codex(){for(const[type,d]of Object.entries(PLANTS)){const a=document.createElement('article');a.innerHTML=`<canvas width="90" height="110"></canvas><div><h4>${d.name}</h4><p>阳光 ${d.cost} · 冷却 ${d.cool} 秒<br>${d.role}</p></div>`;const c=a.querySelector('canvas').getContext('2d');renderer.sprite(c,d.asset,8,d.asset==='TallNut'?2:25,74,d.asset==='TallNut'?106:74,0);$('codex').append(a);}for(const[type,d]of Object.entries(ENEMIES)){const a=document.createElement('article');a.innerHTML=`<canvas width="120" height="130"></canvas><b>${d.name}</b><p>耐久 ${d.hp}${type==='normal'?'':' · 护具破损后露出本体'}</p>`;renderer.sprite(a.querySelector('canvas').getContext('2d'),d.asset,-18,0,150,130,0);$('enemyCodex').append(a);}}
document.addEventListener('keydown',e=>{if($('help').open||!game)return;if(intro){if(e.key==='Escape')finishIntro();return;}if(e.code==='Space'){e.preventDefault();pause();}else if(e.key==='Escape'){selected=null;hint();}else if(!paused){if(e.key.toLowerCase()==='s'){selected='shovel';hint();}else if(/^[1-9]$/.test(e.key)){const type=game.available()[Number(e.key)-1];if(type){selected=type;hint();}}}});document.addEventListener('visibilitychange',()=>{if(document.hidden&&game&&!paused&&!finished)pause();});
$('levelsBtn').onclick=()=>{$('home').hidden=true;$('levelSelect').hidden=false;};$('backLevels').onclick=home;
$('replayIntroBtn').onclick=()=>{$('loading').hidden=false;$('enterBtn').focus();};
$('enterBtn').onclick=()=>{$('loading').hidden=true;home();};
function setCodex(tab){const plants=tab==='plants';$('codex').hidden=!plants;$('enemyCodex').hidden=plants;$('plantTab').setAttribute('aria-pressed',String(plants));$('zombieTab').setAttribute('aria-pressed',String(!plants));$('help').classList.toggle('zombie-page',!plants);}
$('plantTab').onclick=()=>setCodex('plants');$('zombieTab').onclick=()=>setCodex('zombies');
$('optionsBtn').onclick=()=>{$('settingsSound').textContent=$('soundBtn').textContent;$('settingsAuto').textContent=$('autoBtn').textContent;$('settingsGrid').textContent='辅助网格：'+(grid?'开':'关');$('settings').showModal();};
$('closeSettings').onclick=()=>$('settings').close();
$('settingsSound').onclick=()=>{$('soundBtn').click();$('settingsSound').textContent=$('soundBtn').textContent;};
$('settingsAuto').onclick=()=>{$('autoBtn').click();$('settingsAuto').textContent=$('autoBtn').textContent;};
$('settingsGrid').onclick=()=>{$('gridBtn').click();$('settingsGrid').textContent='辅助网格：'+(grid?'开':'关');};
async function boot(){try{renderer=await Renderer.load(f=>{$('loadProgress').value=f;$('loadGrass').style.width=(f*100)+'%';$('loadRoll').style.left=(f*100)+'%';$('loadRoll').style.transform='translate(-50%,-50%) rotate('+(f*900)+'deg)';});codex();home();$('home').hidden=true;$('loadText').textContent='草坪准备好了';document.querySelector('.boot-bottom h2').textContent='欢迎回来';$('enterBtn').hidden=false;}catch(e){$('loadText').textContent=e.message+'，点击重试。';$('retryLoad').hidden=false;}}$('retryLoad').onclick=()=>location.reload();boot();requestAnimationFrame(frame);
})();
